import { useState, useRef, useEffect } from "react";
import { Link, useNavigate } from "react-router-dom";
import PortalSplitLayout from "../../components/layout/PortalSplitLayout";
import OnboardingStepLayout from "../../components/layout/OnboardingStepLayout";
import PendingStatusLayout from "../../components/layout/PendingStatusLayout";
import {
  Field,
  inputClass,
  PageTitle,
  FormDivider,
  OAuthButtons,
  AlertError,
  PrimaryButton,
} from "../../components/ui";
import { getPortal } from "../../theme/portal";
import { canSubmitAccountForm } from "../../utils/accountValidation";
import {
  sendSignupVerificationEmail,
  saveEmailVerificationSession,
  getEmailVerificationErrorMessage,
  isEmailVerified,
  getEmailVerificationSession,
} from "../../services/emailVerificationApi";

const Input = ({ label, placeholder, defaultValue, type = "text" }) => (
  <Field label={label} className="mb-4">
    <input type={type} placeholder={placeholder} defaultValue={defaultValue} className={inputClass} />
  </Field>
);

const bizBenefits = [
  "Post jobs across all 58 wilayas",
  "Browse verified professionals",
  "Commission freelancers directly",
  "Build a verified company presence",
];

export function OnboardingAccount() {
  const navigate = useNavigate();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [agreedToTerms, setAgreedToTerms] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const canContinue = canSubmitAccountForm({
    email,
    password,
    confirmPassword,
    agreedToTerms,
  });

  const handleContinue = async () => {
    if (!canContinue || loading) return;
    const trimmed = email.trim();
    setLoading(true);
    setError("");
    try {
      await sendSignupVerificationEmail("business", trimmed);
      const expiresAt = saveEmailVerificationSession("business", trimmed);
      navigate("/verify-email", { state: { email: trimmed, expiresAt } });
    } catch (err) {
      setError(getEmailVerificationErrorMessage(err));
    } finally {
      setLoading(false);
    }
  };

  return (
    <OnboardingShell>

      <Stepper steps={["Account", "Company", "Documents"]} current={1} />

      <div className="bg-white rounded-[2rem] border border-gray-100 p-10 w-full max-w-lg shadow-sm mt-8">
        <h2 className="font-serif text-3xl font-normal text-navy mb-2">Create your account</h2>
        <p className="text-sm text-gray-400 mb-8">Business credentials for Linkio.</p>


        <div className="space-y-1">
          <div className="flex flex-col gap-1 mb-4">
            <label className="text-sm font-medium">Business Email</label>
            <input
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder="you@company.dz"
              className="px-4 py-3 rounded-xl border border-gray-200 bg-cream text-sm outline-none focus:border-navy focus:bg-white"
            />
          </div>
          <div className="flex flex-col gap-1 mb-4">
            <label className="text-sm font-medium">Password</label>
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder="Enter a password"
              className="px-4 py-3 rounded-xl border border-gray-200 bg-cream text-sm outline-none focus:border-navy focus:bg-white"
            />
          </div>
          <p className="text-[11px] text-gray-400 pb-4">At least 8 characters</p>
          <div className="flex flex-col gap-1 mb-4">
            <label className="text-sm font-medium">Confirm Password</label>
            <input
              type="password"
              value={confirmPassword}
              onChange={(e) => setConfirmPassword(e.target.value)}
              placeholder="Repeat your password"
              className="px-4 py-3 rounded-xl border border-gray-200 bg-cream text-sm outline-none focus:border-navy focus:bg-white"
            />
          </div>
        </div>


        <div className="relative flex items-center justify-center my-6">
          <div className="absolute w-full h-px bg-gray-100" />
          <span className="relative bg-white px-4 text-[11px] text-gray-400 uppercase tracking-widest">
            Or continue with
          </span>
        </div>

        <div className="flex gap-4 mb-6">
          <button className="flex-1 flex items-center justify-center gap-2 py-3 border border-gray-200 rounded-xl text-sm font-medium hover:bg-cream transition-all">
            <GoogleIcon /> Google
          </button>
          <button className="flex-1 flex items-center justify-center gap-2 py-3 border border-gray-200 rounded-xl text-sm font-medium hover:bg-cream transition-all">
            <AppleIcon /> Apple
          </button>
        </div>


        {error && (
          <p className="text-sm text-red-600 bg-red-50 border border-red-100 rounded-lg px-3 py-2 mb-4">
            {error}
          </p>
        )}

        <label className="flex items-start gap-3 text-xs text-gray-500 mb-8 cursor-pointer leading-tight">
          <input
            type="checkbox"
            checked={agreedToTerms}
            onChange={(e) => setAgreedToTerms(e.target.checked)}
            className="w-4 h-4 mt-0.5 accent-navy"
          />
          <span>
            I agree to the <span className="text-navy font-bold underline">Terms of Service</span> and <span className="text-navy font-bold underline">Privacy Policy</span>
          </span>
        </label>

        <button
          type="button"
          disabled={!canContinue || loading}
          onClick={handleContinue}
          className={`w-full py-4 rounded-full text-sm font-bold transition-all
            ${canContinue && !loading
              ? "bg-red text-white hover:bg-red-800 shadow-lg shadow-red/20"
              : "bg-red/40 text-white/80 cursor-not-allowed shadow-none"}`}
        >
          {loading ? "Sending…" : "Continue →"}
        </button>


        <p className="text-sm text-gray-500 text-center mt-6">
          Already have an account?{" "}
          <span className="text-navy font-bold cursor-pointer hover:underline" onClick={() => navigate("/sign-in")}>
            Sign in
          </span>
        </p>
      </div>
    </OnboardingShell>
  );
}

// ── Step 2: Company ───────────────────────────────────────
export function OnboardingCompany() {
  const navigate = useNavigate();
  const logoInputRef = useRef(null);

  useEffect(() => {
    if (!isEmailVerified("business")) {
      const session = getEmailVerificationSession("business");
      if (session?.email) {
        navigate("/verify-email", {
          replace: true,
          state: { email: session.email, expiresAt: session.expiresAt },
        });
      } else {
        navigate("/register", { replace: true });
      }
    }
  }, [navigate]);

  const handleLogoClick = () => {
    logoInputRef.current.click();
  };

  return (
    <OnboardingShell>
      <Stepper steps={["Account", "Company", "Documents"]} current={2} />

      {/* مدخل ملفات مخفي للصور فقط */}
      <input
        type="file"
        ref={logoInputRef}
        className="hidden"
        accept="image/png, image/jpeg, image/svg+xml"
        onChange={(e) => console.log("Logo selected:", e.target.files[0])}
      />

      <div className="bg-white rounded-2xl border border-gray-200 p-8 w-full max-w-2xl mx-auto shadow-sm mt-8">
        <h2 className="font-serif text-2xl font-normal mb-1">Set up your company</h2>
        <p className="text-sm text-gray-500 mb-8">Tell professionals about your business.</p>

        {/* قسم رفع الشعار - أضفنا onClick هنا */}
        <div className="flex flex-col items-center mb-8">
          <div 
            onClick={handleLogoClick}
            className="w-20 h-20 bg-gray-100 border border-gray-200 rounded-2xl flex flex-col items-center justify-center cursor-pointer hover:bg-gray-200 transition-all group"
          >
            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="#9ca3af" strokeWidth="1.5">
              <rect x="3" y="3" width="18" height="18" rx="2" ry="2"/>
              <circle cx="8.5" cy="8.5" r="1.5"/>
              <polyline points="21 15 16 10 5 21"/>
            </svg>
            <span className="text-[10px] text-gray-400 mt-1">Upload logo</span>
          </div>
          <p className="text-[10px] text-gray-400 mt-2">PNG or SVG, max 2MB</p>
        </div>

        {/* باقي الحقول كما هي في تصميمك */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <Input label="Company Name" placeholder="TechCorp Algérie SARL" />
          <Input label="Commercial Register No." placeholder="16B0000000" />
          <Input label="Industry" placeholder="Technology" />
          <Input label="Phone Number" placeholder="+213 21 XXX XXX" />
          <Input label="Wilaya" placeholder="Alger" />
          <Input label="Website" placeholder="https://yourcompany.dz" />
        </div>

        <div className="mt-4 mb-8">
          <Input label="Business Address" placeholder="Full address including street, city" />
        </div>

        <div className="flex justify-between items-center">
          <button onClick={() => navigate(-1)} className="text-sm text-gray-400 hover:text-gray-900">← Back</button>
          <button 
            onClick={() => navigate("/onboarding/documents")}
            className="px-10 py-3 bg-red text-white rounded-full text-sm font-medium hover:bg-red-800 transition-all"
          >
            Next →
          </button>
        </div>
      </div>
    </OnboardingShell>
  );
}

// ── Step 3: Documents ─────────────────────────────────────
export function OnboardingDocuments() {
  const navigate = useNavigate();
  const fileInputRef = useRef(null); // 2. إنشاء المرجع

  const handleUploadClick = () => {
    fileInputRef.current.click(); // 3. وظيفة فتح نافذة الملفات
  };

  return (
    <OnboardingShell>
      <Stepper steps={["Account", "Company", "Documents"]} current={3} />

      {/* مدخل ملفات مخفي تماماً لا يؤثر على التصميم */}
      <input
        type="file"
        ref={fileInputRef}
        className="hidden"
        onChange={(e) => console.log(e.target.files[0])}
        accept=".pdf,image/*"
      />

      <div className="bg-white rounded-2xl border border-gray-200 p-8 w-full max-w-lg">
        <h2 className="font-serif text-2xl font-normal mb-1">Verification documents</h2>
        <p className="text-sm text-gray-500 mb-6">Upload official documents to verify your business identity.</p>

        {/* أضفت فقط onClick هنا */}
        <div 
          onClick={handleUploadClick} 
          className="border-2 border-dashed border-gray-200 rounded-2xl py-12 flex flex-col items-center gap-3 cursor-pointer hover:border-gray-400 transition-all bg-cream mb-4"
        >
          <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="#9ca3af" strokeWidth="1.5">
            <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/>
            <polyline points="14 2 14 8 20 8"/><line x1="16" y1="13" x2="8" y2="13"/><line x1="16" y1="17" x2="8" y2="17"/>
          </svg>
          <p className="text-sm text-gray-500">Upload business verification documents</p>
          <span className="text-xs text-gray-400">Commercial register, tax ID — PDF or image</span>
        </div>

        <div className="bg-yellow-50 border border-yellow-200 rounded-xl px-4 py-3 flex gap-3 text-sm text-yellow-800 mb-6">
          <span>⚠</span>
          <span>Your account must be <strong>verified by our admin team</strong> before you can post announcements. Verification takes 24–48 hours.</span>
        </div>

        <div className="flex justify-between">
          <button onClick={() => navigate("/onboarding/company")} className="text-sm text-gray-400 hover:text-gray-900">← Back</button>
          <button onClick={() => navigate("/onboarding/pending")} className="px-7 py-3 bg-red text-white rounded-full text-sm font-medium hover:bg-red-dark transition-all">Submit →</button>
        </div>
      </div>
    </OnboardingShell>
  );
}

// ── Pending Verification ──────────────────────────────────
export function PendingVerificationPage() {
  const navigate = useNavigate();
  return (
    <div className="min-h-screen bg-cream flex flex-col font-sans">
      <div className="linkio-topbar px-8">
        <LinkioBrand />
        <button type="button" onClick={() => navigate(-1)} className="text-sm text-gray-500 hover:text-navy">
          ← Back
        </button>
      </div>

      <div className="flex-1 flex flex-col items-center justify-center text-center px-6">
        <div className="w-16 h-16 bg-red/10 rounded-full flex items-center justify-center text-2xl mb-6">🕐</div>
        <h1 className="font-serif text-3xl font-normal mb-3">
          Profile submitted —<br />pending verification
        </h1>
        <p className="text-sm text-gray-500 max-w-sm leading-relaxed mb-6">
          Our admin team will review your profile and documents within 24–48 hours.
          You'll receive an email once your account is verified.
        </p>
        <span className="inline-flex items-center gap-2 text-xs font-medium text-yellow-700 bg-yellow-100 border border-yellow-300 px-4 py-2 rounded-full mb-8">
          ⏱ Verification in progress
        </span>
        <button
          className="w-64 py-3.5 bg-red text-white rounded-full text-sm font-medium hover:bg-red-dark transition-all"
          onClick={() => navigate("/dashboard")}
        >
          Preview my profile →
        </button>
      </div>
    </div>
  );
}
